function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:state?.household?.timezone||'America/Sao_Paulo'}).format(new Date())}
function plusDate(d,n){const t=new Date(d+'T12:00:00Z');t.setUTCDate(t.getUTCDate()+n);return t.toISOString().slice(0,10)}
