    const eligible=[...available].sort((a,b)=>(deferred[task.id+':'+a.id]!==undefined?-2:last[task.id+':'+a.id]??-1)-(deferred[task.id+':'+b.id]!==undefined?-2:last[task.id+':'+b.id]??-1)||(deferred[task.id+':'+a.id]??0)-(deferred[task.id+':'+b.id]??0)||position(a)-position(b));
