function titleBlock(title,description,action=''){return `<div class="intro"><div><div class="eyebrow">${dateLabel(today(),true)}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function overdue(t,d){if(d<today())return true;return d===today()&&t.due_time.slice(0,5)<new Intl.DateTimeFormat('en-GB',{timeZone:state.household.timezone,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())}
