const PERSON_PALETTE=[{ink:'#356c55',soft:'#edf5ee'},{ink:'#a2662e',soft:'#faf1e5'},{ink:'#466da4',soft:'#edf2fb'},{ink:'#8560a8',soft:'#f4eef9'},{ink:'#a05073',soft:'#faedf3'},{ink:'#397e81',soft:'#eaf5f5'},{ink:'#86712d',soft:'#f7f3e5'},{ink:'#875c4f',soft:'#f6eeea'}];
function personColors(id){const index=state.members.findIndex(m=>m.id===id);return index<0?{ink:'#858d80',soft:'#f3f4f0'}:PERSON_PALETTE[index%PERSON_PALETTE.length]}
function personFilters(tasks){const selected=tab==='mine'?me()?.id:personFilter;return `<div class="person-filters" role="group" aria-label="Filtrar tarefas por morador"><button class="person-chip ${selected==='all'?'selected':''}" data-person="all" aria-pressed="${selected==='all'}">Todos <small>${tasks.length}</small></button>${state.members.map(m=>{const c=personColors(m.id);return `<button class="person-chip ${selected===m.id?'selected':''}" style="--person-ink:${c.ink};--person-soft:${c.soft}" data-person="${m.id}" aria-pressed="${selected===m.id}"><i></i>${esc(m.name)}${m.id===me()?.id?' (você)':''}<small>${tasks.filter(t=>t.effective===m.id).length}</small></button>`}).join('')}</div>`}
