function sidebar(){return `<div class="right-column"><section class="side-card"><div class="section-top"><h2>Quem está por aqui</h2><small>${state.members.filter(m=>!absent(m.id,today())).length} em casa</small></div>${state.members.map((m,i)=>`<div class="person-row"><span class="avatar" style="background:${personColors(m.id).soft};color:${personColors(m.id).ink}">${esc(m.name.slice(0,1))}</span><div><strong>${esc(m.name)}</strong><small>${absent(m.id,today())?'Tarefas redistribuídas':assignments(today()).filter(t=>t.effective===m.id&&!t.completion).length+' tarefas pendentes'}</small></div><span class="dot">${absent(m.id,today())?'Ausente':'Em casa'}</span></div>`).join('')}<button class="link" data-view="pessoas">Gerenciar pessoas e ausências →</button></section><section class="side-card"><h2>♡ Ajudar sem acumular</h2><p>Quem cobre vai para o fim da fila. Quem foi coberto mantém a próxima vez. Sem dívida adicional.</p><button class="link" data-view="favores">Ver histórico de cuidados →</button></section><section class="side-card quote"><span class="big">❝</span><strong>Uma casa leve é feita de pequenos cuidados compartilhados.</strong><p>Não precisa ser perfeito. Precisa ser em conjunto.</p></section></div>`}
function home(){const all=assignments(day), mine=all.filter(t=>t.effective===me()?.id), done=all.filter(t=>t.completion), pending=all.filter(t=>!t.completion), shown=(tab==='mine'?mine:tab==='done'?done:all).filter(t=>tab==='mine'||personFilter==='all'||t.effective===personFilter);const percent=all.length?Math.round(done.length/all.length*100):0;return titleBlock(`Olá, ${esc(me()?.name||'você')} <em>☀</em>`,'Cada um faz um pouco. A casa agradece.',`<button class="primary" data-action="new-task">＋ Nova tarefa</button>`)+`<section class="hero"><div class="hero-icon">⌂</div><div><h2>${pending.length?'Vamos deixar a casa em dia?':'Tudo em dia por aqui!'}</h2><p>${pending.length?`São ${pending.length} pequenos cuidados para dividir ${day===today()?'hoje':'nesta data'}.`:'Que bom quando o cuidado é compartilhado.'}</p></div><div class="progress"><strong>${done.length} de ${all.length} concluídas</strong><div class="track"><i style="width:${percent}%"></i></div><small>${percent}% do cuidado de hoje</small></div></section><section class="stats"><div class="stat"><span class="stat-icon">◷</span><div><strong>${mine.filter(t=>!t.completion).length}</strong><small>Minhas tarefas pendentes</small></div></div><div class="stat"><span class="stat-icon">✓</span><div><strong>${done.length}</strong><small>Concluídas visíveis para você</small></div></div><div class="stat"><span class="stat-icon">♡</span><div><strong>${state.completions.filter(c=>c.completed_by===me()?.id&&c.original_member_id!==me()?.id&&!c.exempt).length}</strong><small>Vezes em que você ajudou</small></div></div></section><div class="columns"><section><div class="section-top"><h2>Os cuidados do dia</h2><input class="date-picker" type="date" id="homeDate" value="${day}" max="${plusDate(today(),366)}" aria-label="Data das tarefas"></div><div class="tabs"><button data-tab="mine" class="${tab==='mine'?'active':''}">Minhas tarefas (${mine.length})</button><button data-tab="all" class="${tab==='all'?'active':''}">Todas visíveis (${all.length})</button><button data-tab="done" class="${tab==='done'?'active':''}">Concluídas (${done.length})</button></div>${personFilters(tab==='done'?done:all)}${shown.length?shown.map(t=>taskCard(t,day)).join(''):'<div class="empty">✓ Nenhuma tarefa nesta lista.<br>Um respiro também faz parte.</div>'}</section>${sidebar()}</div>`}
function recurrenceText(task){if(task.recurrence==='interval')return 'A cada '+Number(task.interval_days||1)+' dia(s)';if(task.recurrence==='once')return 'Único dia · '+dateLabel(task.starts_on,true);if(task.recurrence==='weekly')return 'Semanal · '+new Date(task.starts_on+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC',weekday:'long'});return 'Todos os dias'}
function catalogCard(task){return `<article class="task catalog-task ${task.active?'':'catalog-archived'}"><div class="task-emoji">${esc(task.emoji)}</div><div class="task-body"><h3>${esc(task.title)}</h3>${visibilityBadge(task)}<div class="recurrence-badge">↻ ${esc(recurrenceText(task))}</div><div class="task-meta"><span>◷ ${task.due_time.slice(0,5)}</span><span>≈ ${task.duration_minutes} min</span>${task.recurrence!=='once'?`<span>Desde ${dateLabel(task.starts_on)}</span>`:''}</div><p class="catalog-rotation">${task.recurrence==='once'?'Responsável definido pelo rodízio nessa data.':'Rodízio independente entre os moradores disponíveis.'}</p><div class="task-actions"><button class="secondary" data-action="edit-task" data-id="${task.id}">${task.active?'Editar tarefa':'Reativar e editar'}</button>${task.active?`<button class="text-btn" data-action="archive" data-id="${task.id}">Arquivar</button>`:''}<button class="text-btn danger" data-action="delete-task" data-id="${task.id}">Excluir</button></div></div><span class="tag ${task.active?'tag-done':''}">${task.active?'Ativa':'Arquivada'}</span></article>`}
